// ViewScores.js
import React from "react";
import { useLocation } from "react-router-dom";
import './ViewScores.css';

const ViewScores = () => {
  const location = useLocation();
  const { score } = location.state || { score: null }; // Get score from location.state

  return (
    <div className="score-container">
      <h2>Your Exam Score</h2>
      {score !== null ? (
        <div className="score">
          <p>Your score is: {score}</p>
        </div>
      ) : (
        <p>Unable to fetch your score. Please try again.</p>
      )}
    </div>
  );
};

export default ViewScores;
